import json,collections,sys
E=lambda r,n: next((e.get('valueDateTime') or e.get('valueString') or e.get('valueDate') or e.get('valueCode') for e in r.get('extension',[]) if e['url'].endswith('/'+n)),None)
D={}
for f in ['Patient','EpisodeOfCare','Condition','Observation','Specimen','Basic','MedicationAdministration','MedicationDispense','DocumentReference','AllergyIntolerance','Task']:
    D[f]=[json.loads(l) for l in open('/tmp/exp/'+f+'.ndjson')]
pats={p['id']:p for p in D['Patient']}
spec={s['id']:s for s in D['Specimen']}
acc=collections.defaultdict(list)
for b in D['Basic']: acc[E(b,'accession')].append(b)
bypat=collections.defaultdict(list)
def subj(r):
    for k in ('subject','patient','for'):
        if k in r: return r[k]['reference'].split('/')[-1]
    return None
for f in D:
    if f in ('Patient',): continue
    for r in D[f]:
        s=subj(r)
        if s: bypat[s].append(r)
def et(r): return E(r,'event-time') or ''
def fmt(r):
    t=r['resourceType']; i=r['id']; e=et(r)[:16]
    if t=='EpisodeOfCare': return f"{e} EPISODE {i} start={r['period']['start']} status={r['status']}"
    if t=='Condition': return f"{e} DX {i} {r['code']['text']} recorded={r.get('recordedDate','')[:10]} by {r.get('recorder',{}).get('display')}"
    if t=='Observation':
        sp=r.get('specimen',{}).get('reference','').split('/')[-1]
        s=spec.get(sp)
        lab=f"label[{E(s,'label-name')}|{E(s,'label-mrn')}|{E(s,'label-dob')}] coll={s['collection'].get('collectedDateTime','')[:16]} by {s['collection'].get('collector',{}).get('display')}" if s else 'NOSPEC'
        an=(r.get('identifier') or [{}])[0].get('value')
        ae=acc.get(an,[])
        aes='; '.join(f"ACC {b['id']} [{E(b,'patient-name')}|{E(b,'patient-mrn')}|{E(b,'patient-dob')}] recv={E(b,'received')[:16]} by {b.get('author',{}).get('display')}" for b in ae) or 'NOACC'
        notes=' | '.join(n['text'] for n in r.get('note',[]))
        return f"{e} OBS {i} {r['code']['text']} status={r['status']} coll={r.get('effectiveDateTime','')[:16]} issued={r.get('issued','')[:16]} val={r.get('valueString')!r} acc={an} notes={notes}\n      SPEC {sp} {lab}\n      {aes}"
    if t=='Specimen': return None
    if t=='MedicationAdministration': return f"{e} MEDADM {i} {r['medicationCodeableConcept']['text']} status={r['status']} dose={r.get('dosage',{}).get('text')} when={r.get('effectiveDateTime','')[:16]} perf={[p['actor']['display'] for p in r.get('performer',[])]} note={[n['text'] for n in r.get('note',[])]}"
    if t=='MedicationDispense': return f"{e} MEDDISP {i} {r['medicationCodeableConcept']['text']} qty={r.get('quantity',{}).get('value')} days={r.get('daysSupply',{}).get('value')} handed={r.get('whenHandedOver','')[:16]} sig={[d['text'] for d in r.get('dosageInstruction',[])]} note={[n['text'] for n in r.get('note',[])]}"
    if t=='DocumentReference': return f"{e} DOC {i} [{r['type']['text']}] role={E(r,'author-role')} author={[a['display'] for a in r.get('author',[])]}\n      TEXT: "+r['description'].replace('\n','\n      ')
    if t=='AllergyIntolerance': return f"{e} ALLERGY {i} {r['code']['text']} reaction={[m['text'] for rr in r.get('reaction',[]) for m in rr['manifestation']]}"
    if t=='Task':
        if r['status']=='requested': return f"{e} REQUEST {i} {r['code']['coding'][0]['code']} focus={r.get('focus',{}).get('reference')} desc={r['description']}"
        return f"{e} ITEM {i} {r.get('businessStatus')}"
    return f"{e} {t} {i}"
ids=sys.argv[1:] if len(sys.argv)>1 else sorted(pats)
for pid in ids:
    p=pats[pid]
    print('#'*90)
    print(f"PATIENT {pid} {p['name'][0]['text']} mrn={p['identifier'][0]['value']} dob={p['birthDate']} sex={p['gender']}")
    for r in sorted(bypat[pid],key=lambda r:(et(r),r['resourceType'])):
        s=fmt(r)
        if s: print('  '+s)
