import json,collections,datetime
L=lambda f:[json.loads(l) for l in open('/tmp/exp/'+f+'.ndjson')]
D={f:L(f) for f in ['Patient','EpisodeOfCare','Condition','Observation','MedicationAdministration','MedicationDispense','DocumentReference','AllergyIntolerance','Task','Specimen','Basic']}
E=lambda r,n: next((e.get('valueDateTime') or e.get('valueString') or e.get('valueDate') for e in r.get('extension',[]) if e['url'].endswith('/'+n)),None)
eps={e['patient']['reference'].split('/')[-1]:e['id'] for e in D['EpisodeOfCare']}
accs={E(b,'accession'):b['id'] for b in D['Basic']}
obs={o['id']:o for o in D['Observation']}
def trio(oid):
    o=obs[oid]; sp=o.get('specimen',{}).get('reference','').split('/')[-1]
    an=(o.get('identifier') or [{}])[0].get('value')
    return [oid,sp,accs.get(an)]
def sub(r):
    for k in ('subject','patient','for'):
        if k in r: return r[k]['reference'].split('/')[-1]
by=collections.defaultdict(lambda: collections.defaultdict(list))
for f in D:
    if f in('Patient','EpisodeOfCare'): continue
    for r in D[f]:
        s=sub(r)
        if s: by[s][f].append(r)
def ids(pid,f,pred=None):
    return [r['id'] for r in sorted(by[pid][f],key=lambda r:E(r,'event-time') or '') if pred is None or pred(r)]
def req(pid,code):
    return [t['id'] for t in by[pid]['Task'] if t['status']=='requested' and t['code']['coding'][0]['code']==code]
def meds(pid): return ids(pid,'MedicationAdministration')
def conds(pid): return ids(pid,'Condition')
def rpr(pid): return ids(pid,'Observation',lambda o:o['code']['text'].startswith('RPR'))
def docs(pid,*kinds): return ids(pid,'DocumentReference',lambda r:r['type']['text'] in kinds)
def docsel(pid,*subs): return [r['id'] for r in sorted(by[pid]['DocumentReference'],key=lambda r:E(r,'event-time')) if any(s in r['description'] for s in subs)]
def dispn(pid): return ids(pid,'MedicationDispense')
ITEMS=[]
def add(pid,issue,disp,me,ev,ex):
    ev=[x for x in dict.fromkeys(ev) if x]
    assert 1<=len(ev)<=30,(pid,issue,len(ev))
    ITEMS.append(dict(patient=pid,episode=eps[pid],issue=issue,disposition=disp,missing_evidence=me,evidence=ev,explanation=ex))
json.dump({'ok':1},open('/tmp/an/tmp.json','w'))
PYEOF
echo ok

